const protoSchema = `
syntax = "proto3";
package Catan.IO;

enum UiType {
    UI_TYPE_DONT_CHANGE = 0;
    UI_TYPE_DEFAULT = 1; // depends on model; UI_TYPE_VOLTAGE preferred
    UI_TYPE_AI_VOLTAGE = 2;
    UI_TYPE_AI_CURRENT_0_20 = 3;
    UI_TYPE_AI_RESISTOR_10K = 4;
    UI_TYPE_AI_RESISTOR_180K = 5;
    UI_TYPE_AI_TEMPERATURE_PT1000_DIN = 6;
    UI_TYPE_AI_TEMPERATURE_PT1000_SAMA = 7;
