// on CTRL

enum AdapterId {
    EN0 = 0;
    EN1 = 1;
}

message Ipv4 {
  bytes ip_address = 1 [(nanopb).max_size = 4, (nanopb).fixed_length = true];             // IPv4 address of the adapter.
  uint32 subnet_mask_cidr = 2;                                                            // Subnet mask for the IPv4 address in CIDR format, 0..32, e.g. /24.
  bytes default_gateway = 3 [(nanopb).max_size = 4, (nanopb).fixed_length = true];        // Default gateway for IPv4 traffic.
  bool is_dhcp = 4;                                                                       // true: DHCP assigned address, false: static address
}

message Ipv6 {
  bytes ip_address = 1 [(nanopb).max_size = 16, (nanopb).fixed_length = true];             // IPv6 address of the adapter.
  uint32 prefix_length_cidr = 2;                                                           // Prefix Length for the IPv6 address in CIDR format, 0..128, e.g. /64.
  bytes default_gateway = 3 [(nanopb).max_size = 16, (nanopb).fixed_length = true];        // Default gateway for IPv6 traffic.
  bool is_dhcp = 4;                                                                        // true: DHCP assigned address, false: static address
}

message Adapter {
  AdapterId id = 1;              // Adapter identifier
  bool enabled = 2;              // true: Adapter is enabled
  bool can_disable = 3;          // true: "enable" can be written (what is not the case for en0)
  bool is_readonly = 4;          // true: "ipv4", "enabled", and "ipv6_enabled" can not be written
  bool ipv6_enabled = 5;         // true: "ipv6" is applicable, false: "ipv4" is applicable
  bool can_disable_ipv6 = 6;     // true: "ipv6_enabled" can be written
  Ipv4 ipv4 = 7;                 // ipv4 configuration data
  Ipv6 ipv6 = 8;                 // ipv6 configuration data
}

message SetAdapter {
  AdapterId id = 1;                    // Adapter identifier
  BooleanSetting enable = 2;           // manipulate Adapter->enabled
  BooleanSetting ipv6_enable = 3;      // manipulate Adapter->ipv6_enabled
  Ipv4Setting ip_address = 5;          // manipulate Adapter->ipv4->ip_address
  Uint32Setting subnet_mask_cidr = 6;  // manipulate Adapter->ipv4->subnet_mask_cidr
  Ipv4Setting default_gateway = 7;     // manipulate Adapter->ipv4->default_gateway; active setting to 0.0.0.0 removes the default gateway
  BooleanSetting set_dhcp = 8;         // manipulate Adapter->ipv4->is_dhcp
}

// read ip config
