message RespTcpIpSettings {
  string hostname = 1  [(nanopb).max_length = 64];          // Hostname for the system.
  repeated Adapter adapters = 2  [(nanopb).max_count = 2];  // List of network adapters with their settings
  bool eee = 3;                                             // Indicates if adapters are running in eco mode
}

// write ip config request
// PATCH coap://<ip>:<port>/sys/ip
message ReqTcpIpSettings {
  repeated SetAdapter adapters = 1  [(nanopb).max_count = 2];  // List of network adapters with their settings.
}

