    message ReqRespInfo {
        // ModelData (fix_data.proto)
        string model_name = 1 [(nanopb).max_length = 64];
        string model_number = 2 [(nanopb).max_length = 16];
        // uint32 model_revision = 3; do not reuse!
        // string hardware_revision = 4 [(nanopb).max_length = 10]; do not reuse!

        // DeviceData (fix_data.proto)
        string serial_no = 5 [(nanopb).max_length = 18];
        bytes mac_id = 6 [(nanopb).max_size = 6, (nanopb).fixed_length = true];
        uint32 mac_id_count = 7;
        string host_id = 8 [(nanopb).max_length = 32];
        // string uuid_type = 9 [(nanopb).max_length = 36]; do not reuse!
        // string uuid_plc_next = 10 [(nanopb).max_length = 36]; do not reuse!
        // string g_tin = 11 [(nanopb).max_length = 14]; do not reuse!
        // string dali_serial_no = 12 [(nanopb).max_length = 8]; do not reuse!

        string model_revision = 13 [(nanopb).max_length = 2];
        uint32 hardware_revision = 14;
        bytes uuid_plc_next = 15 [(nanopb).max_size = 16, (nanopb).fixed_length = true];
        bytes g_tin = 16 [(nanopb).max_size = 6, (nanopb).fixed_length = true];
        bytes knx_serial_no = 17 [(nanopb).max_size = 6, (nanopb).fixed_length = true];
        bytes dali_hardware_version = 18 [(nanopb).max_size = 2, (nanopb).fixed_length = true];
        string bldt = 19 [(nanopb).max_length = 14];
    }

    message RespFwUpdateInfo {

        message FwImageInfo {
            string bldt = 1 [(nanopb).max_length = 14];
            uint32 major = 2;
            uint32 minor = 3;
            uint32 revision = 4;
            uint32 build = 5;
            uint32 size = 6;
        }

        enum BlAction {
            BL_ACTION_NO = 0;
            BL_ACTION_COPY_UPDATE = 1;
            BL_ACTION_AUTO_REPAIR = 2;
