//const toEnumValue = (val) => val == null ? undefined : ((val === "true" || val === true) ? 3 : 2);
const toEnumValue = (val) =>
    val == null || val === "" || val === "undefined"
        ? undefined
        : ((val === "true" || val === true) ? 3 : 2);

const toNumberOrUndefined = (val) =>
    val == null || val === "" || val === "undefined"
        ? undefined
        : Number(val);

const toStringOrUndefined = (val) =>
    val == null || val === "" || val === "undefined" ? undefined : String(val);    

