function clean(obj) {
    Object.keys(obj).forEach(key => {
        const value = obj[key];

        if (value == null) {
            delete obj[key];
            return;
        }

        if (typeof value === "object" && !Array.isArray(value)) {
            clean(value);

            // Spezialfall für deine Protobuf-Setting-Struktur:
            // { setting: 2 } ohne val entfernen,
            // aber reqRespEmpty niemals über diese Regel löschen
            if (
                key !== "reqRespEmpty" &&
                Object.keys(value).length === 1 &&
                value.setting !== undefined &&
                value.val === undefined
            ) {
                delete obj[key];
                return;
            }

            // Leere Objekte entfernen,
            // aber reqRespEmpty: {} erhalten
            if (
                key !== "reqRespEmpty" &&
                Object.keys(value).length === 0
            ) {
                delete obj[key];
            }
        }
    });

    return obj;
}

